_SM_TESTS = r'''
import pytest
from sqlmodel import SQLModel, Session, create_engine, select
import workout_app as app

@pytest.fixture
def engine():
    engine = create_engine("sqlite://")
    SQLModel.metadata.create_all(engine)
    yield engine
    engine.dispose()

@pytest.fixture
def session(engine):
    with Session(engine) as session:
        yield session


@pytest.fixture
def seeded(session):
    session.add_all([app.Workout(id=1, name="Upper"), app.Workout(id=2, name="Push"), app.Exercise(id=1, name="Bench"), app.Exercise(id=2, name="Rows")])
    session.commit()
    return session

def test_composite_key_and_foreign_keys():
    table = app.WorkoutExercise.__table__
    assert set(table.primary_key.columns.keys()) == {"workout_id", "exercise_id"}
    assert {fk.target_fullname for fk in table.foreign_keys} == {"workout.id", "exercise.id"}

def test_link_and_both_relationships(seeded):
    assert app.link_exercise(seeded, 1, 1) is True
    seeded.expire_all()
    assert seeded.get(app.Workout, 1).exercises[0].name == "Bench"
    assert seeded.get(app.Exercise, 1).workouts[0].name == "Upper"

def test_shared_exercise(seeded):
    app.link_exercise(seeded, 1, 1)
    app.link_exercise(seeded, 2, 1)
    app.link_exercise(seeded, 1, 2)
    seeded.expire_all()
    assert {w.id for w in seeded.get(app.Exercise, 1).workouts} == {1, 2}
    assert {e.id for e in seeded.get(app.Workout, 1).exercises} == {1, 2}
    assert [e.id for e in seeded.get(app.Workout, 2).exercises] == [1]

def test_duplicate_link_is_idempotent(seeded):
    assert app.link_exercise(seeded, 1, 1) is True
    assert app.link_exercise(seeded, 1, 1) is True
    assert len(seeded.exec(select(app.WorkoutExercise)).all()) == 1

def test_missing_endpoints(seeded):
    assert app.link_exercise(seeded, 99, 1) is False
    assert app.link_exercise(seeded, 1, 99) is False
    assert seeded.exec(select(app.WorkoutExercise)).all() == []

def test_link_is_durable(seeded, engine):
    app.link_exercise(seeded, 1, 1)
    seeded.close()
    with Session(engine) as check:
        assert check.get(app.WorkoutExercise, (1, 1)) is not None
'''[1:]
_SM_IDS = ['test_composite_key_and_foreign_keys', 'test_link_and_both_relationships', 'test_shared_exercise', 'test_duplicate_link_is_idempotent', 'test_missing_endpoints', 'test_link_is_durable']


import json as _json
from pathlib import Path as _Path
import os as _os
import subprocess as _subprocess
import sys as _sys
import tempfile as _tempfile
import xml.etree.ElementTree as _xml

_SM_RESULTS = None


def _sm_run_tests():
    source = _Path(__file__).read_text().split('# === SUPPLIED SQLMODEL TESTS ===', 1)[0]
    with _tempfile.TemporaryDirectory(prefix='sqlmodel-tests-') as folder:
        work = _Path(folder)
        (work / 'workout_app.py').write_text(source)
        (work / 'test_workout.py').write_text(_SM_TESTS)
        report = work / 'results.xml'
        env = dict(_os.environ)
        for key in ('PYTEST_ADDOPTS', 'PYTEST_PLUGINS', 'PYTHONPATH'):
            env.pop(key, None)
        env['PYTEST_DISABLE_PLUGIN_AUTOLOAD'] = '1'
        try:
            done = _subprocess.run(
                [_sys.executable, '-m', 'pytest', '-c', '/dev/null', '-p', 'no:cacheprovider',
                 '-q', '--tb=short', '--junitxml=' + str(report), str(work / 'test_workout.py')],
                cwd=work, env=env, capture_output=True, text=True, timeout=20)
            if report.exists():
                results = {}
                for case in _xml.parse(report).iter('testcase'):
                    name = case.get('name')
                    failures = [child for child in case if child.tag in ('failure', 'error', 'skipped')]
                    results[name] = ('FAILED ' + name + ' | ' +
                                     (failures[0].text or failures[0].get('message', 'test did not pass'))[-1800:]
                                     if failures else 'passed')
                if set(results) == set(_SM_IDS) and done.returncode in (0, 1):
                    return {key: value.replace('\n', ' | ') for key, value in results.items()}
            error = (done.stdout + done.stderr)[-2200:].replace('\n', ' | ')
        except _subprocess.TimeoutExpired:
            error = 'pytest exceeded 20 seconds'
        except Exception as exc:
            error = str(exc).replace('\n', ' | ')
        return {name: 'FAILED ' + name + ' | ' + error for name in _SM_IDS}


class Solution:
    def run(self, payload: str) -> str:
        global _SM_RESULTS
        target = _json.loads(payload)['test']
        if target == '--list':
            return _json.dumps(_SM_IDS)
        if target not in _SM_IDS:
            return 'Unknown test: ' + str(target)
        if _SM_RESULTS is None:
            _SM_RESULTS = _sm_run_tests()
        return _SM_RESULTS[target]

